<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Altus Web Solutions — Websites & AI That Grow Your Business</title>
<meta name="description" content="Altus Web Solutions builds hand-coded websites, e-commerce stores and practical AI (chatbots, receptionists, automation) for UK businesses. Fixed quotes, SEO-ready, designed to convert.">
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<!-- Aeonik loaded locally -->
<style>
  :root{
    --black:#0A0A12;
    --navy:#242A36;
    --brand:#10B3FE;
    --brand-dark:#1D4ED8;
    --green:#10B3FE;
    --white:#FFFFFF;
    --card:#F4F7FF;
    --muted:#9AA0A6;
    --ink:#212329;
  }
  *{margin:0;padding:0;box-sizing:border-box}
  html{scroll-behavior:smooth}
  body{font-family:'Aeonik',system-ui,sans-serif;background:var(--black);color:var(--white);-webkit-font-smoothing:antialiased;overflow-x:hidden}

  /* ============ FLOATING PILL HEADER ============ */
  .dl-header{position:fixed;top:22px;left:24px;right:24px;z-index:200;animation:headerIn 1s cubic-bezier(.22,1,.36,1) 2.25s both}
  @keyframes headerIn{from{opacity:0;transform:translateY(-28px)}to{opacity:1;transform:none}}
  .dl-bar{display:flex;align-items:center;gap:30px;max-width:1460px;margin:0 auto;padding:14px 26px;border-radius:16px;
    background:rgba(255,255,255,.09);border:1px solid rgba(255,255,255,.16);
    backdrop-filter:blur(22px) saturate(1.4);-webkit-backdrop-filter:blur(22px) saturate(1.4);
    box-shadow:0 18px 50px rgba(0,0,0,.35);transition:background .35s ease,box-shadow .35s ease}
  .dl-header.scrolled .dl-bar{background:#ffffff;border-color:rgba(0,0,0,.06);box-shadow:0 12px 34px rgba(0,0,0,.14)}
  .dl-logo{display:flex;align-items:center;flex-shrink:0}
  .dl-logo img{height:72px;width:auto;display:block;transition:filter .35s ease}
  /* logo swaps via JS */
  .dl-divider{width:1px;height:38px;background:rgba(255,255,255,.18);flex-shrink:0;transition:background .3s}
  .dl-header.scrolled .dl-divider{background:rgba(20,20,30,.14)}
  .dl-tagline{font-size:12px;font-weight:500;line-height:1.5;color:rgba(255,255,255,.62);max-width:172px;transition:color .3s}
  .dl-header.scrolled .dl-tagline{color:rgba(20,20,30,.62)}
  .dl-nav{display:flex;align-items:center;gap:4px;list-style:none;margin:0 auto}
  .dl-nav>li{position:static}
  .dl-nav>li>a{display:flex;align-items:center;gap:7px;padding:10px 14px;font-size:13.5px;font-weight:500;letter-spacing:.02em;color:rgba(255,255,255,.92);text-decoration:none;border-radius:9px;transition:.22s;white-space:nowrap}
  .dl-header.scrolled .dl-nav>li>a{color:#212329}
  .dl-nav>li>a:hover{background:rgba(255,255,255,.12);color:#fff}
  .dl-header.scrolled .dl-nav>li>a:hover{background:rgba(0,0,0,.06);color:#000}
  .dl-nav .caret{width:8px;height:8px;border-right:1.8px solid currentColor;border-bottom:1.8px solid currentColor;transform:rotate(45deg) translateY(-2px);opacity:.7;transition:transform .25s}
  .dl-nav>li:hover .caret{transform:rotate(225deg) translateY(-1px)}
  .free-dot{font-size:9px;font-weight:700;letter-spacing:.06em;background:var(--green);color:#fff;padding:2.5px 7px;border-radius:20px;margin-left:3px}
  .dl-actions{display:flex;align-items:center;gap:16px;margin-left:auto;flex-shrink:0}
  .dl-phone{font-size:13.5px;font-weight:600;color:rgba(255,255,255,.9);text-decoration:none;white-space:nowrap;transition:color .3s}
  .dl-header.scrolled .dl-phone{color:#212329}
  .btn-pill{display:inline-flex;align-items:center;gap:9px;background:var(--brand);color:#fff;font-size:13.5px;font-weight:600;padding:13px 26px;border-radius:100px;text-decoration:none;white-space:nowrap;transition:transform .22s ease,box-shadow .25s ease,background .25s}
  .btn-pill:hover{transform:translateY(-2px);background:var(--brand-dark);box-shadow:0 12px 28px rgba(16,179,254,.4)}
  .dl-header.scrolled .btn-pill{background:#212329}
  .dl-header.scrolled .btn-pill:hover{background:#2A2F3A;box-shadow:0 12px 28px rgba(0,0,0,.3)}
  .btn-outline{display:inline-flex;align-items:center;gap:9px;border:1.6px solid var(--brand);color:#fff;font-size:13.5px;font-weight:600;padding:12px 26px;border-radius:100px;text-decoration:none;white-space:nowrap;transition:.25s}
  .btn-outline:hover{background:var(--brand);transform:translateY(-2px);box-shadow:0 12px 28px rgba(16,179,254,.35)}

  /* mega panel */
  .mega{position:fixed;top:104px;left:24px;right:24px;z-index:190;opacity:0;visibility:hidden;transform:translateY(14px);transition:opacity .3s ease,transform .36s cubic-bezier(.22,1,.36,1),visibility .3s;pointer-events:none}
  .mega.show{opacity:1;visibility:visible;transform:translateY(0);pointer-events:auto}
  .mega-panel{max-width:1460px;margin:0 auto;background:#242A36;border:1px solid rgba(255,255,255,.1);border-radius:20px;padding:40px 44px;display:grid;gap:40px;box-shadow:0 40px 90px rgba(0,0,0,.55);position:relative;overflow:hidden}
  .mega-panel::before{content:"";position:absolute;inset:0;pointer-events:none;background:radial-gradient(500px 260px at 12% 0%,rgba(16,179,254,.14),transparent 60%),radial-gradient(500px 300px at 90% 100%,rgba(16,179,254,.1),transparent 60%)}
  .mega-ai{grid-template-columns:1fr 1fr 1fr 1.25fr}
  .mega-web{grid-template-columns:1fr 1fr 1fr 1.25fr}
  .mcol{position:relative}
  .mcol h4{font-size:11px;font-weight:700;letter-spacing:.22em;color:var(--green);margin-bottom:16px}
  .mcol ul{list-style:none}
  .mcol li{opacity:0;transform:translateY(10px);transition:opacity .3s ease,transform .3s ease}
  .mega.show .mcol li{opacity:1;transform:none}
  .mega.show .mcol li:nth-child(1){transition-delay:.06s}.mega.show .mcol li:nth-child(2){transition-delay:.1s}
  .mega.show .mcol li:nth-child(3){transition-delay:.14s}.mega.show .mcol li:nth-child(4){transition-delay:.18s}
  .mega.show .mcol li:nth-child(5){transition-delay:.22s}.mega.show .mcol li:nth-child(6){transition-delay:.26s}
  .mcol a{display:block;padding:7px 0;font-size:14px;font-weight:500;color:rgba(255,255,255,.72);text-decoration:none;transition:.18s}
  .mcol a:hover{color:#fff;padding-left:8px}
  .mfeat{position:relative;border-radius:16px;overflow:hidden;padding:30px;display:flex;flex-direction:column;justify-content:flex-end;min-height:260px;
    background:radial-gradient(380px 240px at 80% 10%,rgba(16,179,254,.5),transparent 62%),radial-gradient(300px 260px at 8% 95%,rgba(16,179,254,.35),transparent 60%),linear-gradient(140deg,#242A36,#242A36)}
  .mfeat h5{font-size:20px;font-weight:700;line-height:1.3;letter-spacing:-.01em}
  .mfeat p{font-size:13px;color:rgba(255,255,255,.65);margin-top:8px}
  .mfeat .btn-pill{margin-top:18px;width:fit-content}

  /* simple dropdown */
  .dropdown{position:fixed;top:104px;z-index:190;background:#242A36;border:1px solid rgba(255,255,255,.1);border-radius:16px;min-width:330px;padding:14px;opacity:0;visibility:hidden;transform:translateY(12px);transition:.28s;box-shadow:0 30px 70px rgba(0,0,0,.55);pointer-events:none}
  .dropdown.show{opacity:1;visibility:visible;transform:translateY(0);pointer-events:auto}
  .dropdown a{display:block;padding:11px 16px;font-size:14px;font-weight:500;color:rgba(255,255,255,.72);text-decoration:none;border-radius:10px;transition:.18s}
  .dropdown a:hover{color:#fff;background:rgba(16,179,254,.14);padding-left:22px}

  /* mobile */
  .burger{display:none;background:rgba(255,255,255,.1);border:1px solid rgba(255,255,255,.16);border-radius:10px;cursor:pointer;padding:11px 12px}
  .dl-header.scrolled .burger{background:rgba(0,0,0,.05);border-color:rgba(0,0,0,.1)}
  .burger span{display:block;width:22px;height:2px;background:#fff;margin:5px 0;border-radius:2px;transition:.3s}
  .dl-header.scrolled .burger span{background:#111}
  .mmenu{position:fixed;inset:0;z-index:300;background:#212329;padding:30px 30px 46px;overflow-y:auto;transform:translateX(100%);transition:transform .45s cubic-bezier(.22,1,.36,1);display:flex;flex-direction:column}
  .mmenu.open{transform:none}
  .mm-top{display:flex;justify-content:space-between;align-items:center;margin-bottom:24px}
  .mm-top img{height:32px}
  .mm-close{background:none;border:none;color:#fff;font-size:34px;cursor:pointer;line-height:1}
  .mm-links{list-style:none}
  .mm-links>li{border-bottom:1px solid rgba(255,255,255,.09)}
  .mm-links>li>a,.mm-acc{display:flex;justify-content:space-between;align-items:center;width:100%;padding:17px 0;font-size:16px;font-weight:600;color:#fff;text-decoration:none;background:none;border:none;cursor:pointer;font-family:inherit;text-align:left}
  .mm-acc .caret{width:9px;height:9px;border-right:2px solid var(--brand);border-bottom:2px solid var(--brand);transform:rotate(45deg);transition:transform .25s}
  .mm-acc.open .caret{transform:rotate(225deg)}
  .mm-sub{list-style:none;max-height:0;overflow:hidden;transition:max-height .35s ease}
  .mm-sub a{display:block;padding:9px 0 9px 14px;font-size:14px;color:rgba(255,255,255,.65);text-decoration:none}
  .mm-cta{margin-top:32px;display:flex;flex-direction:column;gap:12px}
  .mm-cta .btn-pill{justify-content:center}
  .mm-phone{text-align:center;color:rgba(255,255,255,.7);font-size:14px;font-weight:600;text-decoration:none;padding:12px}

  /* ============ HERO (demo context) ============ */
  .hero{position:relative;min-height:100vh;display:flex;align-items:center;overflow:hidden;background:#212329}
  .hero-vid{position:absolute;inset:-6%;will-change:transform;
    background:
      radial-gradient(1100px 520px at 70% 30%,rgba(16,179,254,.28),transparent 62%),
      radial-gradient(900px 620px at 20% 75%,rgba(64,42,160,.4),transparent 60%),
      radial-gradient(700px 500px at 85% 85%,rgba(16,179,254,.14),transparent 60%),
      linear-gradient(180deg,#0a0a18 0%,#212329 70%);
    animation:vidDrift 16s ease-in-out infinite alternate,bgIn 2.6s cubic-bezier(.22,1,.36,1) 1.05s backwards}
  @keyframes bgIn{from{transform:scale(1.16)}to{transform:scale(1)}}
  @keyframes vidDrift{from{transform:scale(1) translate(0,0)}to{transform:scale(1.12) translate(-2.5%,2%)}}
  .hero-vid::after{content:"";position:absolute;inset:0;background:linear-gradient(180deg,rgba(7,7,15,.25) 0%,transparent 35%,rgba(7,7,15,.55) 100%)}
  .streak{position:absolute;height:2px;border-radius:2px;background:linear-gradient(90deg,transparent,rgba(16,179,254,.8),transparent);filter:blur(1px);animation:streak 9s linear infinite;opacity:.7}
  .streak.s1{width:44vw;top:22%;left:-10%}
  .streak.s2{width:34vw;top:58%;left:20%;animation-delay:-4s;animation-duration:12s}
  @keyframes streak{from{transform:translateX(-30vw)}to{transform:translateX(120vw)}}
  .hero-inner{position:relative;max-width:1460px;margin:0 auto;padding:150px 32px 120px;width:100%}
  .mask{display:block;overflow:hidden}
  .mask>span{display:block;transform:translateY(112%);animation:riseUp 1.05s cubic-bezier(.22,1,.36,1) 1.75s both}
  .mask:nth-child(2)>span{animation-delay:1.89s}.mask:nth-child(3)>span{animation-delay:2.03s}
  @keyframes riseUp{to{transform:translateY(0)}}
  .hero h1{font-size:clamp(44px,7vw,104px);font-weight:800;letter-spacing:-.03em;line-height:1.04}
  .hero h1 .acc{color:var(--brand)}
  .hero-sub{margin-top:26px;max-width:600px;color:rgba(255,255,255,.72);font-size:17px;opacity:0;animation:fadeUp 1s ease 2.4s forwards}
  @keyframes fadeUp{from{opacity:0;transform:translateY(18px)}to{opacity:1;transform:none}}
  .hero-ctas{display:flex;gap:14px;margin-top:36px;flex-wrap:wrap;opacity:0;animation:fadeUp 1s ease 2.55s forwards}
  .trust{position:absolute;bottom:0;left:0;right:0;border-top:1px solid rgba(255,255,255,.1);background:rgba(5,5,10,.45);backdrop-filter:blur(8px);opacity:0;animation:fadeUp 1s ease 2.75s forwards}
  .trust-inner{max-width:1460px;margin:0 auto;padding:18px 32px;display:flex;align-items:center;gap:34px;overflow:hidden}
  .trust-label{font-size:12px;font-weight:600;letter-spacing:.14em;color:rgba(255,255,255,.55);white-space:nowrap;flex-shrink:0}
  .marquee{overflow:hidden;flex:1;mask-image:linear-gradient(90deg,transparent,#000 8%,#000 92%,transparent)}
  .marquee-track{display:flex;gap:54px;width:max-content;animation:marq 26s linear infinite}
  .marquee-track span{font-size:13.5px;font-weight:600;letter-spacing:.1em;color:rgba(255,255,255,.5);white-space:nowrap}
  .marquee-track span b{color:var(--green);font-weight:600}
  @keyframes marq{to{transform:translateX(-50%)}}

  /* ============ DEMO SECTIONS (context) ============ */
  .sec{padding:110px 0}
  .wrap{max-width:1460px;margin:0 auto;padding:0 32px}
  .sec-light{background:var(--white);color:var(--ink)}
  .kicker{font-size:12px;font-weight:700;letter-spacing:.24em;color:var(--brand);margin-bottom:18px}
  .sec h2{font-size:clamp(30px,4vw,56px);font-weight:800;letter-spacing:-.025em;line-height:1.1}
  .sec h2 .grn{color:var(--green)}
  .cards3{display:grid;grid-template-columns:repeat(3,1fr);gap:24px;margin-top:54px}
  .scard{border-radius:24px;padding:44px 38px;background:var(--card);color:var(--ink);transition:.3s;position:relative;overflow:hidden}
  .scard.dark{background:linear-gradient(150deg,#2A2F3A,#212329);color:#fff}
  .scard:hover{background:linear-gradient(150deg,#2A2F3A,#212329);color:#fff;transform:translateY(-6px)}
  .scard:hover p{color:rgba(255,255,255,.65)}
  .scard .ico{width:56px;height:56px;border-radius:16px;background:var(--brand);display:flex;align-items:center;justify-content:center;font-size:24px;color:#fff;margin-bottom:26px}
  .scard.dark .ico{background:var(--green)}
  .scard h3{font-size:22px;font-weight:700;letter-spacing:-.01em;margin-bottom:12px}
  .scard p{font-size:14.5px;color:#3D4048;line-height:1.65;transition:.3s}
  .scard.dark p{color:rgba(255,255,255,.65)}
  .scard .lm{display:inline-flex;align-items:center;gap:8px;margin-top:26px;background:#212329;color:#fff;font-size:13.5px;font-weight:600;padding:12px 24px;border-radius:100px;text-decoration:none;transition:.25s}
  .scard.dark .lm,.scard:hover .lm{background:var(--brand)}
  .reveal{opacity:0;transform:translateY(36px);transition:opacity .8s ease,transform .8s cubic-bezier(.22,1,.36,1)}
  .reveal.in{opacity:1;transform:none}

  .band-dark{background:#212329}
  .stats{display:grid;grid-template-columns:repeat(4,1fr);gap:24px;margin-top:54px}
  .stat b{display:block;font-size:clamp(34px,3.4vw,52px);font-weight:800;letter-spacing:-.02em}
  .stat b em{font-style:normal;color:var(--brand)}
  .stat span{font-size:13.5px;color:var(--muted)}

  .palette{background:#212329;border-top:1px solid rgba(255,255,255,.08)}
  .pal-row{display:flex;gap:14px;flex-wrap:wrap;margin-top:34px}
  .sw{flex:1;min-width:170px;border-radius:16px;padding:22px;min-height:118px;display:flex;flex-direction:column;justify-content:flex-end;gap:4px}
  .sw b{font-size:13.5px}.sw span{font-size:11.5px;opacity:.65}
  .demo-note{padding:34px 0 90px;background:#212329;color:var(--muted);font-size:13px}

  .to-top{position:fixed;right:26px;bottom:26px;width:52px;height:52px;border-radius:50%;background:var(--brand);color:#fff;border:none;font-size:20px;cursor:pointer;z-index:150;opacity:0;visibility:hidden;transform:translateY(12px);transition:.3s;box-shadow:0 10px 26px rgba(16,179,254,.4)}
  .to-top.show{opacity:1;visibility:visible;transform:none}

  /* ============ CINEMATIC INTRO: logo -> background -> hero ============ */
  .intro{position:fixed;inset:0;z-index:1000;background:#212329;display:flex;align-items:center;justify-content:center;
    clip-path:inset(0 0 0 0);transition:clip-path 1.05s cubic-bezier(.76,0,.24,1)}
  .intro.bye{clip-path:inset(0 0 100% 0)}
  .intro-stage{text-align:center}
  .intro-logo{position:relative;display:inline-block;overflow:hidden;border-radius:6px}
  .intro-logo img{height:120px;width:auto;display:block;animation:logoIn 1.1s cubic-bezier(.22,1,.36,1) .1s both}
  @keyframes logoIn{from{opacity:0;transform:translateY(28px) scale(.94)}to{opacity:1;transform:none}}
  .intro-logo::after{content:"";position:absolute;top:0;bottom:0;width:45%;left:-60%;
    background:linear-gradient(105deg,transparent,rgba(255,255,255,.4),transparent);
    transform:skewX(-18deg);animation:shine 1.15s ease .55s forwards}
  @keyframes shine{to{left:135%}}
  .intro-bar{width:132px;height:2px;background:rgba(255,255,255,.12);margin:28px auto 0;border-radius:2px;overflow:hidden}
  .intro-bar i{display:block;height:100%;width:0;background:linear-gradient(90deg,var(--brand),#7CD4FF);animation:barFill 1.25s cubic-bezier(.22,1,.36,1) .2s forwards}
  @keyframes barFill{to{width:100%}}

  @media(max-width:1360px){
    .dl-tagline,.dl-divider{display:none}
  }
  @media(max-width:1120px){
    .dl-nav,.dl-phone{display:none}
    .burger{display:block}
    .dl-bar{gap:16px;padding:12px 18px}
    .mega,.dropdown{display:none}
  }
  @media(max-width:820px){
    .cards3{grid-template-columns:1fr}
    .stats{grid-template-columns:repeat(2,1fr)}
    .dl-actions .btn-pill{display:none}
    .dl-header{left:14px;right:14px;top:14px}
  }
    .band-dark h3{color:#fff !important;}
  </style>
</head>
<body>

<div class="intro" id="intro"><div class="intro-stage"><div class="intro-logo" id="introLogo"></div><div class="intro-bar"><i></i></div></div></div>

<header class="dl-header" id="dlHeader">
